import os
import logging
import time
import threading
from collections import OrderedDict

from robot.output.pyloggingconf import RobotHandler
from robot.api import logger as robot_logger
from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError

try:
    robot_logs_dir = BuiltIn().get_variable_value('${OUTPUT_DIR}')
    from ute_common_abstract_core import logger as core_logging
    core_logging.logging_path = robot_logs_dir
    # map from Robot's ${LOG LEVEL} to AbstractLib's AL_DEBUG_LEVEL (TRACE, DEBUG)
    robot_log_level = BuiltIn().get_variable_value('${LOG LEVEL}')
    if (robot_log_level == 'DEBUG') or (robot_log_level == 'TRACE'):
        os.environ['AL_DEBUG_LEVEL'] = robot_log_level
except RobotNotRunningError:
    pass


bg_loggers = []


def configure_flow_logic_logger():
    """
    Configure logger for logic flow logs
    :return:
    """
    add_robot_redirecting_handler('messaging.flows.logic')


def flush_background_messages():
    """Log messages cached by background threads"""
    for bg_log_handler in bg_loggers:
        bg_log_handler.flush_cached_messages()


def add_robot_redirecting_handler(logger_name):
    """
    Add new RobotRedirectingHandler to given logger.

    :param logger_name: name of logger to which handler is added
    :return: None
    """
    logger = logging.getLogger(logger_name)
    for handler in logger.handlers:
        if isinstance(handler, RobotRedirectingHandler):
            break
    else:
        handler = RobotRedirectingHandler()
        logger.addHandler(handler)
        bg_loggers.append(handler)


class RobotRedirectingHandler(RobotHandler):
    """
    Handler for redirecting log-records from python logging module to
    RobotFramework logger.

    Can be used only in the following situations:
    - logging from python slave threads
    - logging from logger with propagate setting set to False.

    In other cases logs will be duplicated because RobotFramework
    registers RobotHandler during initialization. That RobotHandler
    also redirects log-records into Robot-native logging system but
    does it only:
    - from logging root logger
    - from python main thread (and 'RobotFrameworkTimeoutThread').
    """
    LOGGING_THREADS = robot_logger.librarylogger.LOGGING_THREADS

    def __init__(self):
        super(RobotRedirectingHandler, self).__init__()
        self.lock = threading.RLock()
        self._messages = OrderedDict()
        self._last_flush_time = time.time()
        formatter = logging.Formatter(fmt="at %(asctime)s.%(msecs)03d %(message)s", datefmt="%H:%M:%S")
        self.setFormatter(formatter)

    def emit(self, record):
        """
        Send a log record to Robot-native logger system with
        python logging level translated to Robot logging level.

        :param record:
        :return:
        """
        try:
            message = self.format(record)
            error = None
        except Exception:
            message, error = self._get_message(record)
        level = self._get_robot_logger_level(record.levelno)
        self.write(message, level)
        if error:
            self.write(error, 'DEBUG')

    @staticmethod
    def _get_robot_logger_level(level):
        if level >= logging.ERROR:
            return 'ERROR'
        if level >= logging.WARNING:
            return 'WARN'
        if level >= logging.INFO:
            return 'INFO'
        if level >= logging.DEBUG:
            return 'DEBUG'
        return 'TRACE'

    def write(self, msg, level):
        """Write to Robot logger or cache"""
        with self.lock:
            thread = threading.currentThread().getName()
            if thread in self.LOGGING_THREADS:
                robot_logger.write(msg, level, html=False)
            else:
                message = (msg, level)
                self._messages.setdefault(thread, []).append(message)

    def flush_cached_messages(self):
        """
        Forwards messages logged on background to Robot Framework log.

        Forwards all messages logged by all threads.
        Logged messages are removed from the message storage.

        This method must be called from the main thread.
        """
        now = time.time()
        if now - self._last_flush_time < 0.1:
            return
        self._last_flush_time = now
        thread = threading.currentThread().getName()
        if thread not in self.LOGGING_THREADS:
            raise RuntimeError(
                "Logging background messages is only allowed from the main "
                "thread. Current thread name: %s" % thread)
        with self.lock:
            self._log_all_messages()

    def _log_all_messages(self):
        for thread in list(self._messages):
            robot_logger.write("<b>Logged by '{}'</b>".format(thread), level='DEBUG', html=True)
            for (message, level) in self._messages.pop(thread):
                robot_logger.write(message, level, html=False)
